#include "Diagnostics.h"
#include "ModelCodec.h"
#include <fstream>
#include <iostream>
#include <set>
#include <stdexcept>
void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);}
nova::Params patch(int engine){nova::Params p;p.engine=engine;p.root=69;p.unison=false;p.detune=p.sub=p.fm=p.noise=0;p.fineTune=0;p.waveA=0;p.waveB=1;p.cutoff=19000;p.envAmount=p.resonance=p.lfoDepth=0;p.attack=.001;p.sustain=1;p.delay=p.reverb=p.chorus=p.drive=0;p.tracking=p.residual=0;p.resonance=.7;return p;}
nova::Sound render(nova::Params p,double rate,int note,double seconds=.35){nova::Engine e;e.configure(p);e.prepare(rate);e.noteOn(1,note,1);nova::Sound s;s.sampleRate=rate;s.left.resize(static_cast<size_t>(rate*seconds));s.right=s.left;e.render(s.left.data(),s.right.data(),static_cast<int>(s.left.size()));return s;}
nova::SpectralModel model(int note,float amplitude=1){nova::SpectralModel m;m.count=1;m.root=note;m.duration=.5;for(int f=0;f<nova::modelFrames;++f)m.times[f]=m.duration*f/(nova::modelFrames-1);m.partials[0].frequency=static_cast<float>(440*std::pow(2.,(note-69)/12.));m.partials[0].amplitude.fill(amplitude);m.partials[0].frequencyRatio.fill(1);return m;}
int main(int argc,char** argv){try{
 for(double rate:{8000.,22050.,44100.,48000.,96000.})for(int engine:{0,2,3,4})for(int note:{48,69,84}){auto s=render(patch(engine),rate,note);double energy=nova::soundRms(s);check(energy>1e-5,"new engine audible");for(float x:s.left)check(std::isfinite(x)&&std::abs(x)<1,"engine bounded/finite");nova::analyse(s);double expected=440*std::pow(2.,(note-69)/12.);double cents=1200*std::log2(s.estimatedHz/expected);if(!s.tonal||std::abs(cents)>6){std::cerr<<"Pitch case: engine="<<engine<<" rate="<<rate<<" note="<<note<<" hz="<<s.estimatedHz<<" cents="<<cents<<'\n';throw std::runtime_error("engine tuning across rates and notes");}}
 auto a=patch(2),b=a;a.fm=0;b.fm=1;b.waveB=1;auto left=render(a,48000,69),right=render(b,48000,69);double difference=0;for(size_t i=0;i<left.left.size();++i)difference+=std::pow(left.left[i]-right.left[i],2);check(difference>.1,"wavetable scan changes shape");
 nova::ZoneBank bank;bank.count=4;bank.zones[0]={model(48,.25),.25f};bank.zones[1]={model(48,.9),.95f};bank.zones[2]={model(72,.25),.25f};bank.zones[3]={model(72,.9),.95f};check(bank.valid(),"valid multi note bank");check(bank.select(48,.2)==0&&bank.select(48,1)==1&&bank.select(72,.2)==2&&bank.select(72,1)==3,"note and velocity choose correct zone");
 auto bytes=nova::encodeZones(bank);nova::ZoneBank restored;check(nova::decodeZones(bytes.data(),bytes.size(),restored)&&restored.count==4,"zone bank round trip");check(restored.zones[3].model.partials[0].amplitude==bank.zones[3].model.partials[0].amplitude,"zone oscillator data exact");check(!nova::decodeZones(bytes.data(),bytes.size()-1,restored),"truncated zones rejected");auto corrupted=bank;corrupted.zones[0].velocity=NAN;check(nova::encodeZones(corrupted).empty(),"invalid zone velocity rejected");
 nova::Engine e;auto p=patch(1);p.root=69;p.useZones=true;e.configure(p);e.prepare(48000);e.setZoneBank(&bank);e.noteOn(1,60,.3);check(e.lastZone()==0,"live engine selects zone");nova::Sound sound;sound.sampleRate=48000;sound.left.resize(24000);sound.right=sound.left;e.render(sound.left.data(),sound.right.data(),24000);nova::analyse(sound);check(sound.tonal&&std::abs(1200*std::log2(sound.estimatedHz/261.625565))<1.2,"zone root transposes to played note, not global root");
 auto loud=left;for(auto* c:{&loud.left,&loud.right})for(float& x:*c)x*=3;nova::normaliseAudition(left);nova::normaliseAudition(loud);check(std::abs(nova::soundRms(left)-nova::soundRms(loud))<1e-6,"A/B level equalisation");auto d=nova::diagnose(left,loud);check(d.sourceTonal&&d.resultTonal&&std::abs(d.resultCents)<1.2,"pitch diagnostic");check(d.bodyError<.001&&d.envelopeError<.001,"identical timbre diagnostic");
 auto original=render(patch(2),22050,69,.5);auto target=nova::makeTarget(original,69,22050,false);target.tonal=true;std::atomic<bool> cancel{false};std::vector<int> stages;int previous=0;auto report=nova::fitInstrument(target,patch(0),140,cancel,[&](int trial,int total,double){check(trial>=previous&&trial<=total,"monotonic progress budget");previous=trial;},[&](int stage){stages.push_back(stage);});check(report.fit.valid&&report.fit.trials==140&&report.multiNeuralUsed,"multi engine search completes budget");check(stages==std::vector<int>({0,1,2,3}),"explicit search stages");for(int i=1;i<4;++i)check(report.stageErrors[i]<=report.stageErrors[i-1]+1e-9,"later stages retain better candidate");for(double loss:report.engineErrors)check(std::isfinite(loss)&&loss<999,"all five engines evaluated");check(report.fit.parameters.sub==0&&report.fit.parameters.fineTune==0&&report.fit.parameters.chorus==0,"search avoids octave sub and drift");
 cancel.store(true);auto cancelled=nova::fitInstrument(target,p,100,cancel);check(cancelled.fit.cancelled||!cancelled.fit.valid,"cancelled search not applied");
 check(argc==2,"multi holdout path");std::ifstream f(argv[1],std::ios::binary);std::array<float,186> row{};int rows=0,wins=0;double mse=0;
 while(f.read(reinterpret_cast<char*>(row.data()),sizeof(row))){std::array<float,155> x{};std::copy(row.begin(),row.begin()+155,x.begin());auto proposal=nova::inferMultiProposal(x);int cls=static_cast<int>(row[185]);for(int j=0;j<30;++j){auto value=proposal.genes[cls][j];check(std::isfinite(value)&&value>=0&&value<=1,"multi inference bounded");mse+=std::pow(value-row[155+j],2);}int predicted=static_cast<int>(std::max_element(proposal.priority.begin(),proposal.priority.end())-proposal.priority.begin());wins+=predicted==cls;++rows;}
 check(rows==96&&mse/(rows*30)<.035&&wins>60,"deployed multi neural holdout");std::cout<<"Multi network: rows="<<rows<<" MSE="<<mse/(rows*30)<<" classification="<<wins<<"/"<<rows<<'\n';
 std::cout<<"PASS: 60 engine/rate/note cases, wavetable morph, note/velocity zones, serialization, audition levels, diagnostics, all engines, staged search, cancellation and multi neural inference\n";
}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
